{
  "词条": "残星会",
  "关键词": ["FRACTSIDUS", "人工共鸣技术", "前文明遗孤", "模糊势力", "剧本操控"],
  "性质": "索拉里斯世界中通过人工诱导共鸣技术推动人类与残像（声骸）融合的阵营，行为逻辑介于工具化牺牲与自主牺牲之间",
  "目标使命": {
    "终极目标": {
      "核心诉求": "摧毁索拉里斯世界现有秩序，强制推动全人类进化为高阶共鸣者",
      "新文明构建": "建立以声骸融合技术为核心的文明体系"
    },
    "行动纲领": {
      "技术实现": "研发残像声骸与人类机械耦合技术",
      "关键计划": [
        "二次共鸣技术开发",
        "岁主复制计划（聚械机偶为实验体）",
        "诱导黑潮事件重塑世界"
      ]
    }
  },
  "核心成员": [
    {
      "代号": "伤痕",
      "定位": "会监级战力",
      "能力": "空间传送支援，构成超时空战术体系核心"
    },
    {
      "代号": "弗洛洛",
      "定位": "指挥家（目前暂时离开残星会）",
      "能力": "彼岸花媒介操控残象大军",
      "背景": "因陨石灾难失去亲人，试图复活逝者"
      "目前状态":与索诺拉"失亡彼岸"融合
    },
    {
      "代号": "克里斯托弗",
      "定位": "剧作家",
      "能力": "剧本操控（提前排演剧本，将剧本代入现实世界，强制现实世界事件按预设结局发展）",
      "特征": "被描述为纯粹恶人，建立乌鸦情报网络"
    },
  ],
  "技术体系": {
    "核心科技": "人工诱导共鸣技术",
    "战术架构": {
      "三人体系": "伤痕（空间传送） + 弗洛洛（残象召唤） + 克里斯托弗（战略布局）",
      "监视网络": "红瞳乌鸦群覆盖多区域，实时监控关键目标"
    },
    "能力限制": "剧本操控需依托事件原有逻辑框架，分阶段覆写实现"
  },
  "剧情事件": [
    {
      "事件": "拉古那人性实验",
      "内容": "克里斯托弗潜伏十数年引导民众推翻教会，验证反抗意志"
    },
    {
      "事件": "七丘时间牢笼",
      "内容": "克里斯托弗发动三日循环剧本，漂泊者介入打破死亡循环"
    },
    {
      "事件": "弗洛洛的背叛",
      "内容": "与漂泊者短暂结盟后因复活逝者理念冲突决战坠海"
    }
  ],
  "组织关系": {
    "隐海修会": "战略合作，利用其信仰解释权增强鸣式力量",
    "黑海岸": "形成牺牲理念对照（残星会主张主动牺牲，黑海岸倾向被动承受）",
  },
  "设计特征": {
    "视觉符号": [
      "乌鸦（监视网络载体）",
      "彼岸花（弗洛洛能力媒介）",
      "剧本书（克里斯托弗操控工具）"
    ],
    "叙事风格": [
      "谜语人对话强化神秘性",
      "前文明遗孤背景深化矛盾",
      "病娇/疯批气质突显角色极端性"
    ]
  }
}

