      "当前状态": "存活（恢复中）",
      "形态特征": "形似蛟龙",
      "特殊事件": "曾施展时序之力造成乘霄山的时流异象"
    },
    "英白拉多": {
      "关键词": ["Impellidor", "Unicorn Sentinel", "Rinascita Guardian"],
      "所属地域": "黎那汐塔",
      "共鸣对象": "卡提希娅",
      "当前状态": "陨落",
      "形态特征": "形似独角兽、天马",
    }
  },
  "文化影响": {
    "宗教崇拜": "被各地居民奉为神明般的存在",
    "精神支柱": "成为人类面对灾难时的希望象征",
    "文明守护": "见证并记录着人类文明的兴衰历程"
  },
  "能力表现": {
